// Some portions generated by Claude
'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');

const graphAdditions = require(require('./workbench-scripts.js').workbenchScriptPath('graphAdditions.js'));

// "Add to graph" on the Workbench pages queues resources, statements and queries for the Graph page of the same
// repository, which takes them when it opens (see tools/workbench/src/main/frontend/graph-explorer/graph-additions.ts).
function memoryStorage() {
    const values = new Map();
    return {
        getItem: (key) => (values.has(key) ? values.get(key) : null),
        setItem: (key, value) => values.set(key, String(value)),
        removeItem: (key) => values.delete(key),
        values
    };
}

const context = { basePath: '/wb/', repositoryId: 'my repo', serverIdentity: 'server' };

test('a resource is queued under the repository of the page', () => {
    const storage = memoryStorage();
    assert.equal(graphAdditions.add(context, { kind: 'resource', term: '<urn:a>' }, storage), 1);
    assert.deepEqual([...storage.values.keys()], ['rdf4j-workbench-graph-additions:["repository-v2","/wb","server","my repo"]']);
    assert.deepEqual(graphAdditions.pending(context, storage), [{ kind: 'resource', term: '<urn:a>' }]);
});

test('the same addition is queued once, statements and queries alongside resources', () => {
    const storage = memoryStorage();
    graphAdditions.add(context, { kind: 'resource', term: '<urn:a>' }, storage);
    graphAdditions.add(context, [
        { kind: 'resource', term: '<urn:a>' },
        { kind: 'statement', subject: '<urn:a>', predicate: '<urn:p>', object: '"x"@en' },
        { kind: 'query', query: 'CONSTRUCT WHERE { ?s ?p ?o } LIMIT 5' }
    ], storage);
    assert.deepEqual(graphAdditions.pending(context, storage).map((entry) => entry.kind), ['resource', 'statement', 'query']);
});

test('a node is queued on its own, apart from the same resource with its neighbours', () => {
    const storage = memoryStorage();
    graphAdditions.add(context, [
        { kind: 'node', term: '<urn:Type>', query: 'ignored' },
        { kind: 'resource', term: '<urn:Type>' },
        { kind: 'node', term: '<urn:Type>' }
    ], storage);
    assert.deepEqual(graphAdditions.pending(context, storage), [
        { kind: 'node', term: '<urn:Type>' },
        { kind: 'resource', term: '<urn:Type>' }
    ]);
    assert.equal(graphAdditions.add(context, { kind: 'node', term: 'not a term' }, storage), 0);
});

test('malformed entries and unreadable storage are ignored', () => {
    const storage = memoryStorage();
    assert.equal(graphAdditions.add(context, { kind: 'resource', term: 'not a term' }, storage), 0);
    assert.equal(graphAdditions.add(context, { kind: 'nonsense' }, storage), 0);
    storage.setItem(graphAdditions.storageKey(context), '{broken');
    assert.deepEqual(graphAdditions.pending(context, storage), []);
    const failing = { getItem() { throw new Error('denied'); }, setItem() { throw new Error('denied'); } };
    assert.equal(graphAdditions.add(context, { kind: 'resource', term: '<urn:a>' }, failing), 0);
});

test('the queue keeps the newest 500 additions', () => {
    const storage = memoryStorage();
    const entries = Array.from({ length: 510 }, (_, index) => ({ kind: 'resource', term: `<urn:r${index}>` }));
    assert.equal(graphAdditions.add(context, entries, storage), 500);
    const pending = graphAdditions.pending(context, storage);
    assert.equal(pending[0].term, '<urn:r10>');
    assert.equal(pending[499].term, '<urn:r509>');
});

test('the Graph page of the repository', () => {
    assert.equal(graphAdditions.graphUrl(context), '/wb/repositories/my%20repo/graph');
});


test('queue producers isolate identical repository IDs by resolved server identity', () => {
    const storage = memoryStorage();
    const a = { ...context, serverIdentity:'sha256:a' };
    const b = { ...context, serverIdentity:'sha256:b' };
    graphAdditions.add(a, {kind:'resource',term:'<urn:a>'}, storage);
    graphAdditions.add(b, {kind:'resource',term:'<urn:b>'}, storage);
    assert.notEqual(graphAdditions.storageKey(a), graphAdditions.storageKey(b));
    assert.deepEqual(graphAdditions.pending(a, storage), [{kind:'resource',term:'<urn:a>'}]);
    assert.deepEqual(graphAdditions.pending(b, storage), [{kind:'resource',term:'<urn:b>'}]);
    assert.equal(graphAdditions.add({ ...context, serverIdentity:undefined }, {kind:'resource',term:'<urn:unknown>'}, storage), 0);
    assert.deepEqual(graphAdditions.pending({ ...context, serverIdentity:undefined }, storage), []);
});

test('a write through the Workbench gives the repository a new data revision the Graph page watches', () => {
    const storage = memoryStorage();
    const key = 'rdf4j-workbench-data-revision:["repository-v2","/wb","server","my repo"]';
    assert.equal(graphAdditions.dataRevisionKey(context), key);
    graphAdditions.dataChanged(context, storage);
    const first = storage.getItem(key);
    assert.ok(first, 'the revision is written');
    graphAdditions.dataChanged(context, storage);
    assert.notEqual(storage.getItem(key), first, 'every write gives a new revision');

    const untracked = memoryStorage();
    graphAdditions.dataChanged({ basePath: '/wb', repositoryId: 'r' }, untracked);
    assert.equal(untracked.values.size, 0, 'without a server identity there is no Graph page to tell');
});

test('creating or deleting a repository changes the data revision of that repository id', () => {
    const storage = memoryStorage();
    const app = { getAttribute: (name) => ({ 'data-workbench-base-path': '/wb', 'data-workbench-server-identity': 'server' })[name] ?? null };
    const document = { getElementById: (id) => (id === 'workbench-app' ? app : null) };
    graphAdditions.repositoryChanged('my repo', document, storage);
    assert.ok(storage.getItem('rdf4j-workbench-data-revision:["repository-v2","/wb","server","my repo"]'));
});
